BEGIN;
SELECT set_config('app.current_user_id','00003001-0000-0000-0000-000000000001',true),set_config('app.current_tenant_id','00003002-0000-0000-0000-000000000001',true),set_config('app.correlation_id','00003003-0000-0000-0000-000000000001',true),set_config('app.current_operation','catalog.brands.create',true);SET LOCAL ROLE mastererp_app;
DO $$ DECLARE item jsonb;supplier jsonb;caught boolean:=false;BEGIN item:=catalogo.marca_crear('acme','ACME','Marca','/images/acme.png','https://acme.invalid','brand-key');IF item->>'slug'<>'acme' THEN RAISE EXCEPTION 'Brand mismatch';END IF;PERFORM set_config('app.current_operation','catalog.brands.update',true);item:=catalogo.marca_actualizar('acme',1,'{"status":"INACTIVE"}');IF(item->>'version')::int<>2 THEN RAISE EXCEPTION 'Brand update mismatch';END IF;PERFORM set_config('app.current_operation','catalog.suppliers.create',true);supplier:=catalogo.proveedor_crear('SUP-1','Proveedor Uno','{"email":"supplier@example.invalid"}','{"payment_days":30}','supplier-key');IF supplier->>'name'<>'Proveedor Uno' THEN RAISE EXCEPTION 'Supplier mismatch';END IF;PERFORM set_config('app.current_operation','catalog.suppliers.update',true);supplier:=catalogo.proveedor_actualizar((supplier->>'id')::uuid,1,'{"status":"BLOCKED"}');IF supplier->>'status'<>'BLOCKED' THEN RAISE EXCEPTION 'Supplier update mismatch';END IF;BEGIN PERFORM catalogo.proveedor_actualizar((supplier->>'id')::uuid,1,'{"status":"ACTIVE"}');EXCEPTION WHEN serialization_failure THEN caught:=true;END;IF NOT caught THEN RAISE EXCEPTION 'Stale supplier accepted';END IF;IF has_table_privilege('mastererp_app','catalogo.marcas','INSERT,UPDATE,DELETE') OR has_table_privilege('mastererp_app','catalogo.proveedores_catalogo','INSERT,UPDATE,DELETE') THEN RAISE EXCEPTION 'Direct DML leaked';END IF;END $$;ROLLBACK;
