INSERT INTO plataforma.roles(code,name) VALUES('qa-catalog-rest','Catalog rest fixture');
INSERT INTO plataforma.role_permissions(role_id,permission_code) SELECT r.id,p.code FROM plataforma.roles r CROSS JOIN plataforma.permissions p WHERE r.code='qa-catalog-rest' AND p.code IN('catalog.brands.read','catalog.brands.write','catalog.suppliers.read','catalog.suppliers.write');
INSERT INTO plataforma.users(id,email,display_name) VALUES('00003001-0000-0000-0000-000000000001','qa-rest@example.invalid','Catalog rest');INSERT INTO plataforma.tenants(id,code,slug,name,status) VALUES('00003002-0000-0000-0000-000000000001','qa-rest','qa-rest','Catalog rest','active');
INSERT INTO plataforma.user_tenants(tenant_id,user_id,role_id,status) SELECT '00003002-0000-0000-0000-000000000001','00003001-0000-0000-0000-000000000001',id,'active' FROM plataforma.roles WHERE code='qa-catalog-rest';INSERT INTO plataforma.tenant_modules(tenant_id,module_id,status) SELECT '00003002-0000-0000-0000-000000000001',id,'active' FROM plataforma.modules WHERE code='erp.catalog';
